// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _run(uint256 depositAmount, uint256 rewardRate) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.setRewardRate(rewardRate) {} catch { return; }
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint256 obs;
        try c.claim() returns (uint256 __r) { obs = __r; } catch { return; }
        assertTrue(obs == depositAmount * rewardRate);
    }

    function testFuzz_run(uint256 depositAmount, uint256 rewardRate) public {
        _run(depositAmount, rewardRate);
    }

    receive() external payable {}
}
